def norm(cells):
    ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))
def transforms(cells):
    res=set()
    cur=cells
    for _ in range(4):
        cur=[(y,x) for y,x in cur]  # rot
        res.add(norm(cur))
        res.add(norm([(y,-x) for y,x in cur]))
        cur=[(x,-y) for y,x in cur]
    return res
